"""Request and response bodies of the API."""
from typing import Any

from pydantic import BaseModel


class UserInfoRequest(BaseModel):
    # the user id is generated by /init: a client-sent user_id is ignored
    age: int | None = None
    gender: str | None = None
    income: str | None = None
    city: str | None = None
    religion: str | None = None
    language: str | None = None
    gpa: float | None = None
    hs: str | None = None
    mbti: str | None = None
    career_goal: str | None = None
    lat: float | None = None
    lon: float | None = None
    prefer_close: bool = False

class InitResponse(BaseModel):
    user_id: str
    created_at: str


class AnswerItem(BaseModel):
    question_id: int
    answer: int

class AnswerRequest(BaseModel):
    user_id: str
    question_id: int
    # deliberately untyped: /answer validates it itself so a bad value comes back
    # in the AnswerResponse shape instead of FastAPI's generic 422
    answer: Any = None

class AnswerResponse(BaseModel):
    prev: int
    answer: Any | None = None
    error: str | None = None

class NextQuestionResponse(BaseModel):
    id: int
    question: str

class FinalRankResponse(BaseModel):
    # entries, best first: majors_info documents without _id
    #   {dept_id, full_name, full_name_en, description, description_ar, lat, lon, gpa, hs,
    #    gender, web, is_private, tags, mbti}
    top_depts: list[dict[str, Any]]


class SessionGoneResponse(BaseModel):
    """Body of a 410 Gone from /next_q: the user's quiz session (user_vector, asked_ids,
    current question) is not in the SessionManager, either because its TTL expired or because
    /init was never called for this user_id. The client must call /init again; the
    old user_id cannot be resumed."""
    user_id: str
    error: str


class MissingFieldsResponse(BaseModel):
    """Body of a 422 Unprocessable Content from /init: the request parsed, but fields the quiz
    needs (hs, gender, gpa: the eligibility filter is built from them) are missing or null."""
    error: str
    missing: list[str]


class RequestValidationErrorResponse(BaseModel):
    """FastAPI's own 422 body, sent before the endpoint runs when the request does not match
    its declared types (e.g. a non-integer question_id, a missing user_id, malformed JSON)."""
    detail: list[dict[str, Any]]


class SearchRequest(BaseModel):
    query: str

class BranchRequest(BaseModel):
    branch: str

class MajorSearchRequest(BaseModel):
    # every field is optional; the filters that are given are combined (AND)
    query: str | None = None       # text match over all string fields
    tags: list[str] | None = None  # docs having any of these tags
    mbti: str | None = None
    hs: str | None = None
    gpa: float | None = None       # docs whose gpa <= this
    lat: float | None = None       # lat + lon -> only docs within 100 km, closest first
    lon: float | None = None
